NotaryLaws.register({"id":"plzp","abbr":"ПЛЗП","title":{"bg":"Правилник за легализациите, заверките и преводите на документи и други книжа","en":"Regulations on Legalisations, Certifications and Translations of Documents"},"group":"other","source":"https://lex.bg/laws/ldoc/-23555583","retrieved":"2026-10-21","partial":false,"articles":30,"inForce":"В сила от 12.09.1958 г.","published":"Обн. ДВ. бр.73 от 12 Септември 1958г.","lastChange":"изм. ДВ. бр.31 от 7 Април 2023г.","items":[{"k":"h","t":"Глава първа. ОБЩИ РАЗПОРЕДБИ"},{"k":"a","n":"1","p":["Чл. 1. (Изм. - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г., изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) (1) Легализирането и заверяването на документи и други книжа се извършва в страната от Министерството на външните работи, а в чужбина - от дипломатическите и консулските представителства на Република България.","(2) (Изм. - ДВ, бр. 7 от 2019 г., в сила от 01.01.2019 г.) Удостоверяването на документи по реда, посочен в Конвенцията за премахване на изискването за легализация на чуждестранни публични актове, се извършва от Министерството на външните работи, Министерството на правосъдието, Националния център за информация и документация и областните администрации в качеството им на органи, оправомощени от Република България да издават удостоверението по чл. 3, ал. 1 от тази конвенция."]},{"k":"a","n":"2","p":["Чл. 2. (Изм. - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г., изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г., доп. - ДВ, бр. 39 от 2020 г.) Лицата, които извършват легализации, заверки и удостоверяване на документи съгласно компетентността на ведомствата по чл. 1, се определят с писмена заповед, издадена от съответния министър или областен управител, или от изпълнителния директор на Националния център за информация и документация, а за дипломатическите и консулските представителства на Република България - от ръководителя на представителството."]},{"k":"a","n":"2а","p":["Чл. 2а. (Нов - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г., изм. - ДВ, бр. 103 от 1990 г., отм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.)"]},{"k":"h","t":"Глава втора. ЛЕГАЛИЗАЦИИ"},{"k":"a","n":"3","p":["Чл. 3. (Доп. - ДВ, бр. 77 от 1976 г., изм. - ДВ, бр. 77 от 1983 г., изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Министерството на външните работи легализира документи и други книжа, издадени от централните органи на изпълнителната власт, както и на учреждения, подведомствени на отделно министерство или пряко на Министерския съвет, само ако те са заверени от последните. Документи, издавани от органи на общинската администрация, нуждаещи се от легализация, се заверяват от кмета на общината или от упълномощено от него длъжностно лице."]},{"k":"a","n":"4","p":["Чл. 4. (Доп. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Министерството на външните работи легализира документи и други книжа, издадени от учреждения, които не са пряко подведомствени нито на отделно министерство, нито на Министерския съвет, както и от обществено-политически, масови, стопански, културно-просветни и други организации, само след като те бъдат заверени от централните ръководства на тези учреждения и организации, когато това се изисква или приема от държавата, в която ще се използват."]},{"k":"a","n":"5","p":["Чл. 5. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Министерството на външните работи легализира преписи от официални документи и други книжа, ако те са надлежно удостоверени от нотариус и Министерството на правосъдието."]},{"k":"a","n":"6","p":["Чл. 6. Легализация на документи и други книжа, подписани от частни лица, се извършва само ако подписите на тези лица са нотариално заверени, а подписът на нотариуса е заверен от Министерството на правосъдието."]},{"k":"a","n":"7","p":["Чл. 7. След като бъде легализиран от Министерството на външните работи, документът трябва да бъде заверен от дипломатическото или консулското представителство на страната, за която е предназначен."]},{"k":"a","n":"8","p":["Чл. 8. Министерството на външните работи легализира документи и други книжа, произхождащи от друга страна, само ако те са заверени от намиращото се в България дипломатическо или консулско представителство на тази страна или от дипломатическото или консулското представителство на страната, поела защитата на нейните интереси в България."]},{"k":"a","n":"9","p":["Чл. 9. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Министерството на външните работи и дипломатическите и консулските представителства на Република България легализират фотокопия от документи и други книжа, ако последната заверка е положена върху фотокопието в оригинална форма."]},{"k":"a","n":"10","p":["Чл. 10. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Всяко дипломатическо и консулско представителство на Република България може да заверява подписите и печатите на Министерството на външните работи и на всички останали дипломатически и консулски представителства на Република България."]},{"k":"a","n":"11","p":["Чл. 11. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г., изм. - ДВ, бр. 31 от 2023 г.) Всяко дипломатическо и консулско представителство на Република България легализира документи и други книжа, издадени в чужди страни, само ако документите са вече заверени:","1. от Министерството на външните работи на приемащата страна;","2. от регионални служби на Министерството на външните работи на приемащата страна, или","3. от други изрично оправомощени съгласно местното законодателство компетентни органи, при условие че съответното българско дипломатическо и консулско представителство е било официално уведомено за това от Министерството на външните работи на приемащата страна;","и разполага с образци от подписите и печатите на длъжностните лица, извършили заверката."]},{"k":"a","n":"12","p":["Чл. 12. (1) (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Легализации на документи и други книжа, произхождащи от страна, с която Република България няма дипломатически отношения, се извършват от дипломатическите или консулските представителства на Република България в трета страна, където има представителство, и на страната, от която произхожда документът. В тези случаи документът се легализира само ако има заверка от чуждото представителство на страната, от която произхожда документът, и от Министерството на външните работи на третата страна, в която се намират чуждото и българското представителство.","(2) В някои случаи Министерството на външните работи легализира направо такива документи и книжа, но само ако те са заверени от Министерството на външните работи на страната, от която произхождат.","(3) Ако страната е възложила защитата на нейните интереси на друга страна, документът се легализира от дипломатическото или консулското представителство на тази страна."]},{"k":"a","n":"13","p":["Чл. 13. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Чужди документи, легализирани от дипломатическите или консулските представителства на Република България, не се нуждаят от допълнителна заверка и са валидни на територията на страната."]},{"k":"a","n":"14","p":["Чл. 14. (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Документи по гражданското състояние на лицата, издадени от органи на чужда държава, не се нуждаят от заверка, ако са изпратени по дипломатически път. В такъв случай се извършва служебно заверен превод на актовете, като извършеният превод съставлява неразделна част от оригиналния акт, който се изпраща по служебен път на съответната администрация по постоянен адрес на българския гражданин."]},{"k":"a","n":"15","p":["Чл. 15. Съдебни документи, изпратени по дипломатически път при изпълнение на съдебни поръчки, не се нуждаят от заверка, освен ако чуждата страна не поиска изрично това."]},{"k":"a","n":"16","p":["Чл. 16. На базата на взаимност министерството изпраща безплатно актове, удостоверения или служебно заверени преписи от актовете по гражданското състояние на заинтересуваната страна, чието гражданство носи лицето."]},{"k":"h","t":"ЗАВЕРКА НА ПОДПИСИ"},{"k":"a","n":"17","p":["Чл. 17. (Отм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.)"]},{"k":"h","t":"Глава втора \"а\". УДОСТОВЕРЯВАНЕ НА ДОКУМЕНТИ ПО РЕДА НА КОНВЕНЦИЯТА ЗА ПРЕМАХВАНЕ НА ИЗИСКВАНЕТО ЗА ЛЕГАЛИЗАЦИЯ НА ЧУЖДЕСТРАННИ ПУБЛИЧНИ АКТОВЕ (НОВА - ДВ, БР. 39 ОТ 2020 Г.)"},{"k":"a","n":"17а","p":["Чл. 17а. (Нов - ДВ, бр. 39 от 2020 г.) (1) Удостоверяването на документи по реда, който е посочен в Конвенцията за премахване на изискването за легализация на чуждестранни публични актове, се извършва чрез издаване на удостоверението \"апостил\" по чл. 3, ал. 1 от конвенцията. Удостоверяват се истинността на подписа, качеството, в което е действало лицето, подписало документа, и при необходимост автентичността на печата или марката, които са поставени върху документа.","(2) За Република България оправомощени да издават удостоверението по ал. 1 са:","1. Министерството на правосъдието - за документи, издавани от орган или длъжностно лице, свързано с правораздавателна система на държавата, включително документите, издавани от прокурор, секретар на съд или призовкар, нотариалните актове, или официалните заверки, като записвания в регистър или удостоверяване на дата или подпис върху частен документ;","2. Националният център за информация и документация - за образователни и удостоверителни документи, издавани от висшите училища, от институциите в системата на предучилищното, училищното и професионалното образование и обучение и от Министерството на образованието и науката и неговите звена;","3. областните администрации - за документи, издавани от кметовете и общинските администрации;","4. Министерството на външните работи - за всички останали административни документи, ако са снабдени със заверката по чл. 3 и 4.","(3) При издаването на удостоверението по ал. 1 администрацията по ал. 2, т. 1 предоставя административните услуги в срок 2 работни дни.","(4) При издаването на удостоверението по ал. 1 администрацията по ал. 2, т. 2 предоставя административните услуги в срок до три работни дни за документи, които не са налични в публичните регистри, които се поддържат от Министерството на образованието и науката. При издаване на удостоверението на документи, налични в публичните регистри, поддържани от Министерството на образованието и науката, предоставя електронни административни услуги в срок до осем работни часа.","(5) При издаването на удостоверението по ал. 1 администрациите по ал. 2, т. 3 и 4 организират работата си така, че административната услуга да се предоставя в срок до осем работни часа, а ако обективни обстоятелства налагат по-дълъг срок - до два работни дни."]},{"k":"h","t":"Глава трета. ПРЕВОДИ"},{"k":"a","n":"18","p":["Чл. 18. (Изм. - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г., изм. - ДВ, бр. 103 от 1990 г.) (1) (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г., отм. с Решение № 15844 от 18.12.2018 г. на ВАС - ДВ, бр. 41 от 2019 г., в сила от 21.05.2019 г.)","(2) (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г., отм. с Решение № 15844 от 18.12.2018 г. на ВАС - ДВ, бр. 41 от 2019 г., в сила от 21.05.2019 г.)","(3) (Нова - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Ръководителите на дипломатическите и консулските представителства на Република България в чужбина определят лицата, които могат да извършват преводи на документи и други книжа от български на чужд език и от чужд на български език, в приемащата държава и в държавите на акредитация, когато тези документи са легализирани по реда, посочен в глава втора на този правилник, удостоверени по реда на Конвенцията за премахване на изискването за легализация на чуждестранни публични актове или освободени от изискванията за легализация."]},{"k":"a","n":"19","p":["Чл. 19. (Изм. - ДВ, бр. 10 от 1964 г., изм. - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г., изм. - ДВ, бр. 103 от 1990 г., отм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.)"]},{"k":"a","n":"20","p":["Чл. 20. Преводи от един чужд език на друг не се извършват направо, а само след като документът бъде преведен от единия чужд език на български, а след това от български на втория чужд език. В този случай се събират такси и за двата превода."]},{"k":"a","n":"21","p":["Чл. 21. Преводи, в които са допуснати поправки, заличавания, вмъквания и изтривания, са невалидни."]},{"k":"a","n":"21а","p":["Чл. 21а. (Нов - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) (1) За чуждестранен документ, преведен на български език по реда на този правилник на територията на Република България и предназначен за ползване в Република България, е необходимо подписът на преводача, положен в извършения от него превод, да бъде нотариално удостоверен в Република България. При удостоверяване на подписа преводачът представя пред нотариуса и документа по чл. 18, ал. 2.","(2) За български документ, преведен на чужд език по реда на този правилник на територията на Република България и предназначен за ползване в чужбина, подписът на преводача, положен в извършения от него превод, се заверява от Министерството на външните работи, ако такава заверка се изисква или приема от държавата, в която ще се използва."]},{"k":"h","t":"Глава четвърта. ТАКСИ"},{"k":"a","n":"22","p":["Чл. 22. (1) (Изм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.) Таксите за легализация и преводи в Министерството на външните работи и в дипломатическите и консулските представителства на Република България се събират съобразно със Закона за държавните такси, тарифите към него и инструкциите по приложението му от натоварените с писмена заповед за това лица, които отговарят за верността на извършените преводи, за редовността на положените заверки и за събраните такси.","(2) (Отм. - ДВ, бр. 95 от 2017 г., в сила от 01.03.2018 г.)"]},{"k":"a","n":"23","p":["Чл. 23. (Отм. - ДВ, бр. 96 от 1982 г., в сила от 01.01.1983 г.)"]},{"k":"a","n":"24","p":["Чл. 24. Освобождаването от такси за легализация и преводи се допуска само в случаите, предвидени в Закона за държавните такси, тарифите към него и чл. 167 от Кодекса на труда."]},{"k":"h","t":"Глава пета. ЗАКЛЮЧИТЕЛНИ РАЗПОРЕДБИ"},{"k":"a","n":"25","p":["Чл. 25. Разпоредбите на този правилник са задължителни, доколкото в сключените спогодби и споразумения с чужди страни не се предвижда друго."]},{"k":"a","n":"26","p":["Чл. 26. При настъпване на изключителни и непредвидени събития и обстоятелства от естество да направят неприложими разпоредбите на настоящия правилник Министерството на външните работи издава специални разпоредби, установяващи временен режим на легализации и преводи, с оглед да се обезпечи защитата на българските интереси."]},{"k":"a","n":"27","p":["Чл. 27. Настоящият правилник влиза в сила от деня на обнародването му в \"Известия на Президиума на Народното събрание\"."]},{"k":"x","t":"ПОСТАНОВЛЕНИЕ № 9 ОТ 18 ЯНУАРИ 2019 Г. ЗА ИЗМЕНЕНИЕ И ДОПЪЛНЕНИЕ НА НОРМАТИВНИ АКТОВЕ НА МИНИСТЕРСКИЯ СЪВЕТ","p":["Новини","Нарушен е балансът между властите: Конституционният съд „отмени“ новата формула за заплатите на младшите магистрати","20.10.2026 17:05","Почина съдия Габриела Христова-Декова","20.10.2026 15:54","За втори път Съдийската колегия не допусна съдийка от Бургас до изборите за ВСС","20.10.2026 15:11","Спектър","ОББ удължи до края на 2026 г. срока за безплатно внасяне на левове по сметки в евро","2026-10-20","Форум","Чл.159 Ал. 1 от ЗДП","от renito80 на 20.10 12:31 1 мнения","Чл. 33 ЗС - действително уговорени условия","от bvoykov на 19.10 16:26 13 мнения","Незаконна фотография","от kpts_ на 19.10 13:06 2 мнения","Посети форума","©","Lex.bg","общи условия","политика за поверителност","за нас","реклама"]}]});
